#!/usr/bin/env bash
# Cross-language LEC: compiled Pyrope (impl) vs the original Verilog (ref).
#
# `lhd lec` takes lg: inputs generated by `lhd compile` — the Verilog side
# needs its slang options (-F filelist, -DSYNTHESIS to compile away CIRCT's
# `ifndef SYNTHESIS $error/$fatal blocks), so it is compiled first:
#   lhd compile verilog --top T --emit-dir lg:ref.lg -- -F filelist.f -DSYNTHESIS
#
#   MODE=pass  equivalence must be PROVEN (exit 0).
#   MODE=bug   bug1 variant (ALU 32-bit add flipped to subtract) must be
#              caught: non-zero exit AND a refutation, not a crash.
#   MODE=incr  three runs sharing one --workdir (formal_cache.json under it):
#              cold, identical warm re-run (cache hits asserted), then a
#              comment1 recompile (still equivalent, still warm).
RF="${TEST_SRCDIR:-${RUNFILES_DIR:-$0.runfiles}}"
. "$RF/_main/bench/common.sh"

copy_dino_sources src

run_timed compile_ref lhd compile verilog --top PipelinedDualIssueCPU \
  --emit-dir lg:ref.lg --workdir cw_ref -- -F "$DINO_V_DIR/filelist.f" -DSYNTHESIS

compile_impl() {  # OUT_LG — compile the (possibly variant-overlaid) copy
  rm -rf "$1"
  lhd compile src/pyrope/PipelinedDualIssueCPU.prp --top PipelinedDualIssueCPU \
    --emit-dir "lg:$1" --workdir "cw_$1"
}

lec_run() {  # IMPL_LG
  lhd lec --impl "lg:$1" --ref lg:ref.lg --top PipelinedDualIssueCPU --workdir LW
}

case "${MODE:?}" in
pass)
  run_timed compile_impl compile_impl impl1
  run_timed lec_pass lec_run impl1
  if grep -qia "refut" step_lec_pass.log; then
    echo "FAIL: identical designs reported a refutation" >&2
    exit 1
  fi
  echo "PASS: pyrope impl == verilog ref (lec ${LAST_MS} ms)"
  ;;
bug)
  apply_variant bug1 src/pyrope
  run_timed compile_bug compile_impl implb
  run_expect_fail lec_bug lec_run implb
  if ! grep -qiaE "refut|equiv_fail" step_lec_bug.log; then
    echo "FAIL: lec failed on bug1 but not as a refutation:" >&2
    tail -30 step_lec_bug.log >&2
    exit 1
  fi
  echo "PASS: injected ALU bug refuted (lec ${LAST_MS} ms)"
  ;;
incr)
  run_timed compile_p1 compile_impl impl1
  run_timed lec_cold lec_run impl1
  run_timed lec_warm lec_run impl1
  grep -qa "lec\[cache\]" step_lec_warm.log \
    || { echo "FAIL: warm identical re-run reported no verdict-cache use" >&2; exit 1; }

  apply_variant comment1 src/pyrope
  run_timed compile_p3 compile_impl impl3
  run_timed lec_touch lec_run impl3
  echo "PASS: cold/warm/comment-touch lec runs all equivalent"
  ;;
*)
  echo "FAIL: unknown MODE=$MODE" >&2
  exit 2
  ;;
esac
